 if (numeric) {
  const kind = numeric[1] === 'an integer' ? ['पूर्णांक','ಪೂರ್ಣ ಸಂಖ್ಯೆ'] : ['सीमित संख्या','ಸೀಮಿತ ಸಂಖ್ಯೆ'];
  return index === 0 ? `${numeric[2]} और ${numeric[3]} के बीच ${kind[index]} अपेक्षित है।` : `${numeric[2]} ಮತ್ತು ${numeric[3]} ನಡುವಿನ ${kind[index]} ಅಗತ್ಯ.`;
 }
 const job = /^Job status changed to (queued|printing|ready|collected)\.$/.exec(key);
