 const printer = /^Printer changed to (operational|paused|maintenance)\.$/.exec(key);
 if (printer) return index === 0 ? `प्रिंटर स्थिति बदली: ${translate(printer[1], language)}।` : `ಮುದ್ರಕ ಸ್ಥಿತಿ ಬದಲಾಗಿದೆ: ${translate(printer[1], language)}.`;
 const storage = /^Could not open local storage: ([\s\S]+)$/.exec(key);
 if (storage) {
  const detail = storage[1] === 'permission denied' ? ['अनुमति नहीं मिली','ಅನುಮತಿ ನಿರಾಕರಿಸಲಾಗಿದೆ'][index] : translate(storage[1], language);
  return index === 0 ? `स्थानीय स्टोरेज नहीं खुला: ${detail}` : `ಸ್ಥಳೀಯ ಸಂಗ್ರಹ ತೆರೆಯಲಾಗಲಿಲ್ಲ: ${detail}`;
 }
